package agent

import (
	"context"
	"fmt"
	"path/filepath"
	"strings"
)

const (
	// recentlyModifiedBlockLeadIn introduces the list of files the session
	// wrote. Like the manifest it is generated by code, so the paths are
	// facts rather than the model's recollection of what it edited.
	recentlyModifiedBlockLeadIn = "## Recently Modified Files"

	// recentlyModifiedLimit caps the list. The summary is context, not an
	// inventory: the five most recent writes are what a resuming agent needs
	// to re-open, and a longer list would crowd out the prose that says why.
	recentlyModifiedLimit = 5
)

// recentlyModifiedBlock renders the pointer to the files this session wrote.
// Paths are made relative to workingDir when they live under it, matching the
// manifest's file list; a path outside the workspace keeps its absolute form
// because there is no meaningful relative spelling.
//
// The block lists paths only and deliberately does not include file contents:
// re-reading is the caller's decision, priced by what `view` costs.
func recentlyModifiedBlock(paths []string, workingDir string) string {
	if len(paths) == 0 {
		return ""
	}

	seen := make(map[string]struct{}, len(paths))
	var lines []string
	for _, path := range paths {
		if path == "" {
			continue
		}
		display := displayPath(path, workingDir)
		if _, ok := seen[display]; ok {
			continue
		}
		seen[display] = struct{}{}
		lines = append(lines, "- "+display)
		if len(lines) == recentlyModifiedLimit {
			break
		}
	}
	if len(lines) == 0 {
		return ""
	}

	return recentlyModifiedBlockLeadIn + "\n\n" +
		"This session created or modified the files below. Their current contents " +
		"are not in this summary: open them with `view` before editing or quoting them.\n\n" +
		strings.Join(lines, "\n")
}

// displayPath shortens a path to a workspace-relative one when it is inside
// workingDir. A relative path that escapes (starts with `..`) is not shorter,
// so the absolute form is kept instead.
func displayPath(path, workingDir string) string {
	if workingDir == "" {
		return path
	}
	rel, err := filepath.Rel(workingDir, path)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return path
	}
	return filepath.ToSlash(rel)
}

// recentWritePaths fetches the paths for [recentlyModifiedBlock]. It is split
// out so the block renderer stays pure and testable without a tracker.
//
// Only writes are fetched. The ledger also records shell commands, but a
// command is not a modified file and listing one under this heading would
// claim an edit that may not have happened.
func (a *sessionAgent) recentWritePaths(ctx context.Context, sessionID string) ([]string, error) {
	if a.filetracker == nil {
		return nil, nil
	}
	paths, err := a.filetracker.ListRecentWrites(ctx, sessionID, recentlyModifiedLimit)
	if err != nil {
		return nil, fmt.Errorf("listing recent writes: %w", err)
	}
	return paths, nil
}
